import { asArrayFirst, toFiniteFirst, toFiniteVector, } from '@cornerstonejs/utils';
import { readOwn } from '../safeFunctions/index.js';
import { planeGeometry } from './seriesFunctions.js';
const SPACING_TOLERANCE = 0.2;
const item = (value) => asArrayFirst(value);
